import heapq


def shortest_path(edges, start, end):
    """
    Find the shortest path in a directed weighted graph using Dijkstra's algorithm.

    Args:
        edges: List of (from_node, to_node, weight) tuples representing one-way roads.
        start: Starting node.
        end: Ending node.

    Returns:
        Tuple of (distance, path) where distance is the shortest total distance
        and path is an ordered list of nodes on that path.
        If start and end are the same, return (0, [start]).
        If no path exists, return (None, None).
        If any edge weight is negative, raise ValueError.
    """
    # Check for negative weights
    for from_node, to_node, weight in edges:
        if weight < 0:
            raise ValueError("Negative edge weights are not allowed.")

    if start == end:
        return (0, [start])

    # Build adjacency list
    adj = {}
    for from_node, to_node, weight in edges:
        if from_node not in adj:
            adj[from_node] = []
        adj[from_node].append((to_node, weight))

    # Dijkstra's algorithm
    # dist[node] = shortest distance from start to node
    dist = {start: 0}
    prev = {}  # To track the path
    # Priority queue: (distance, node)
    pq = [(0, start)]

    visited = set()

    while pq:
        d, u = heapq.heappop(pq)
        if u in visited:
            continue
        visited.add(u)

        if u == end:
            break

        if u in adj:
            for v, w in adj[u]:
                if w < 0:
                    raise ValueError("Negative edge weights are not allowed.")
                if v not in dist or d + w < dist[v]:
                    dist[v] = d + w
                    prev[v] = u
                    heapq.heappush(pq, (d + w, v))

    if end not in dist:
        return (None, None)

    # Reconstruct path
    path = []
    node = end
    while node != start:
        path.append(node)
        if node not in prev:
            # Should not happen if end is in dist
            return (None, None)
        node = prev[node]
    path.append(start)
    path.reverse()

    return (dist[end], path)
